function overviewJobActivity(job){if(state.direction!=='b'||state.tableView!=='overview')return '';return '<div class="source-job-activity">'+jobUpdatesIndicator(job)+'<button class="source-job-files" data-action="job-files" data-id="'+job.id+'" title="'+(job.attachments?job.attachments+' attached '+(job.attachments===1?'file':'files'):'No attached files')+'" aria-label="Open Project Files for '+h(job.number||job.name)+': '+job.attachments+' attachments">'+icon('clip')+(job.attachments||'')+'</button></div>';}
function markFixtureUpdatesSeen(jobId){const fixture=jobUpdateFixtures.get(jobId);if(fixture)fixture.hasUnseenActivity=false;}
function fixtureJobUpdatesPanel(job){const fixture=jobUpdateFixtures.get(job.id),items=fixture?.updates||[];return '<div class="detail-main"><h3>Job Updates ('+items.length+')</h3>'+(items.map(update=>'<div class="message-bubble"><strong>'+h(update.author)+'</strong><p>'+h(update.text)+'</p><small>'+h(update.time)+'</small></div>').join('')||'<div class="empty">No job updates</div>')+'<form id="job-update-form" class="compose"><input name="update" required aria-label="Write a job update" placeholder="Write a job update…"><button class="primary" '+(state.role==='readonly'?'disabled':'')+'>'+sourceIcon('message')+'Post update</button></form></div>';}

function filteredJobs(){return jobs.filter(j=>(state.status==='all'?active.includes(j.status):state.status==='all_jobs'||j.status===state.status)&&`${j.name} ${j.customer} ${j.number} ${j.order}`.toLowerCase().includes(state.search.toLowerCase())).sort((a,b)=>state.sort==='delivery'?a.delivery.localeCompare(b.delivery):state.sort==='recent'?b.number.localeCompare(a.number):Object.keys(statuses).indexOf(a.status)-Object.keys(statuses).indexOf(b.status));}
// Accepted summary scope: ProductionWorkspace.tsx:675-683,969-970,1147-1167.
// Keep this independent of the proposed KPI cards and Pipeline/Monthly Workload filters.
function pipelineSummaryCounts(shown=filteredJobs()){
  const queue=jobs.filter(j=>!['complete','cancelled'].includes(j.status)).map(j=>state.pending[j.id]?{...j,start:state.pending[j.id].start,finish:state.pending[j.id].finish}:j);
  const scheduled=queue.filter(j=>Boolean(j.start&&j.finish)).length;
  // Follow-ups are independent of update totals/unseen; current fixtures have none.
  const attention=queue.filter(j=>!j.number?.trim()||!j.customer?.trim()||!j.delivery||j.labor===null||(jobUpdateFixtures.get(j.id)?.openFollowUpCount??0)>0).length;
  return {unscheduled:queue.length-scheduled,attention,active:queue.length,scheduled,showing:shown.length};
}
function pipelineSummary(shown){
  const c=pipelineSummaryCounts(shown);
  return `<div id="pipeline-summary" class="pipeline-summary" data-production-attention-strip data-has-unscheduled="${c.unscheduled>0}" role="group" aria-label="Production Pipeline summary"><div class="pipeline-summary-attention"><span class="pipeline-unscheduled" title="Jobs other than Complete or Cancelled missing either planned date; proposed dates are included">${c.unscheduled?icon('warning')+'<strong>'+c.unscheduled+'</strong> Unscheduled':'All active jobs scheduled'}</span><span title="Jobs missing planning details or with unresolved follow-ups; independent of material readiness and unread updates"><strong>${c.attention}</strong> Need Attention</span></div><dl class="pipeline-summary-totals"><div title="All jobs other than Complete or Cancelled, including Shipped"><dt>Active Jobs</dt><dd>${c.active}</dd></div><div title="Active Jobs with both planned dates, including proposed dates"><dt>Scheduled</dt><dd>${c.scheduled}</dd></div><div title="Jobs matching the current Pipeline search and filters"><dt>Showing</dt><dd data-pipeline-showing>${c.showing}</dd></div></dl></div>`;
}
function jobTable(){const list=filteredJobs();return `<section class="panel" aria-label="Production jobs">${state.direction==='b'?pipelineSummary(list):''}<div class="panel-head"><h2>Production Pipeline</h2><span class="chip">${list.length} jobs</span><span class="spacer"></span><div class="segmented" role="group" aria-label="Pipeline view">${['overview','table','timeline'].map(v=>`<button data-action="table-view" data-value="${v}" aria-pressed="${state.tableView===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div><div class="table-toolbar"><label class="search">${state.direction==='b'?'':icon('search')}<input id="job-search" aria-label="Search Pipeline jobs" placeholder="Search project, customer or job number…" value="${h(state.search)}"></label><select id="status-filter" aria-label="Pipeline status filter"><option value="all" ${state.status==='all'?'selected':''}>Active jobs</option><option value="all_jobs" ${state.status==='all_jobs'?'selected':''}>All jobs</option>${Object.keys(statuses).map(v=>`<option value="${v}" ${v===state.status?'selected':''}>${statuses[v][0]}</option>`).join('')}</select><label class="select-label">Sort<select id="sort">${[['status','Status'],['delivery','Delivery'],['recent','Recently added']].map(([v,l])=>`<option value="${v}" ${v===state.sort?'selected':''}>${l}</option>`).join('')}</select></label><span class="spacer"></span><button data-action="columns">${sourceIcon('columns','more')} Columns</button></div><div id="job-results">${jobResults(list)}</div><div class="table-foot"><span>${list.length} displayed · ${jobs.length} synthetic jobs</span><span>Schedule changes require review</span></div></section>`;}

// Overview uses the accepted sibling-overlay interaction model; dense Table is unchanged.
function isModernOverview(){return state.direction==='b'&&state.tableView==='overview';}
function overviewHitbox(job){return isModernOverview()?'<button type="button" class="job-row-hitbox" data-action="job" data-id="'+job.id+'" aria-label="Open '+h(job.name)+' Inspector"><span class="review-sr-only">Open job details</span></button>':'';}
function overviewTitle(job){return isModernOverview()?'<span class="job-link">'+h(job.name)+'</span>':jobAction(job);}
function overviewOpenAction(job,mobile=false){return isModernOverview()?'<span class="job-open-chevron" aria-hidden="true">'+icon('chevron')+'</span>':'<button class="icon ghost" data-action="job" data-id="'+job.id+'" aria-label="'+(mobile?'Inspect ':'Open ')+h(job.name)+(mobile?'':' Inspector')+'">'+icon(state.direction==='b'?'search':'chevron')+'</button>';}

function jobResults(list){if(!list.length)return '<div class="empty">No jobs match these Pipeline filters. Monthly Workload keeps its own filters.</div>';if(state.tableView==='timeline')return timeline(list);const dense=state.tableView==='table';return `<div class="table-container desktop-job-table" tabindex="0" aria-label="Production job table, scroll horizontally for all fields"><table ${dense?'style="min-width:1920px"':''}><thead><tr><th>Project / Customer</th><th>Job #</th>${dense?'<th>Estimate</th><th>Work order</th><th>Deposit</th>':''}<th>Production status</th><th>Material</th><th>Planned start</th><th>Planned finish</th><th>Delivery</th><th>Labor</th>${dense?'<th>Calendar days</th><th>Color plate</th><th>Sample</th><th>Approval</th><th>Operations</th><th>Remarks</th>':''}<th>Open</th></tr></thead><tbody>${list.map(j=>`<tr class="${isModernOverview()?'overview-hit-row':''}"><td class="job-identity">${overviewHitbox(j)}${overviewTitle(j)}<div class="job-meta">${h(j.customer)}${state.direction==='b'&&state.tableView==='overview'?'':`<span class="row">${icon('clip')}${j.attachments}</span>`}</div>${overviewJobActivity(j)}</td><td class="mono">${h(j.number)}</td>${dense?`<td>${h(j.estimate)}</td><td>${h(j.order)}</td><td>Oct 19</td>`:''}<td>${badge(j.status)}</td><td>${material(j.material)}</td><td>${state.direction==='b'&&!j.start?'<span class="needs-dates">'+icon('warning')+'Needs Dates</span>':date(j.start)}</td><td>${date(j.finish)}</td><td>${date(j.delivery)}</td><td class="mono">${j.labor} h</td>${dense?`<td>${j.start?Math.round((new Date(j.finish)-new Date(j.start))/86400000)+1:'—'}</td><td>CP-0${jobs.indexOf(j)+1}</td><td>Approved</td><td>Oct 26</td><td>${h(j.owner)}</td><td style="min-width:240px">${h(j.remarks)}</td>`:''}<td>${overviewOpenAction(j)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-job-list">${list.map(j=>`<article class="job-card ${isModernOverview()?'overview-hit-card':''}">${overviewHitbox(j)}<div class="row between">${overviewTitle(j)}${overviewOpenAction(j,true)}</div><div class="job-meta">${h(j.number)} · ${h(j.customer)} · ${j.attachments} files</div><div class="job-card-bottom">${badge(j.status)}${material(j.material)}</div><div class="job-meta">${state.direction==='b'&&!j.start?'<span class="needs-dates">'+icon('warning')+'</span>':''}Planned ${date(j.start)}–${date(j.finish)} · Delivery ${date(j.delivery)} · ${j.labor} h</div>${overviewJobActivity(j)}</article>`).join('')}</div>`;}
function timeline(list){return `<div class="calendar-info">Representative weekly rendering · stage dates in the Inspector. Drag/resize is outside this review.</div><div class="table-container" tabindex="0" aria-label="Weekly timeline"><div class="timeline-demo"><div class="timeline-row"><span class="eyebrow">November 9–15, 2026</span>${['Mon 9','Tue 10','Wed 11','Thu 12','Fri 13','Sat 14','Sun 15'].map(d=>`<span class="muted">${d}</span>`).join('')}</div>${list.map(j=>{const s=Math.max(0,Math.min(6,Math.round((new Date(j.start||'2026-11-09')-new Date('2026-11-09'))/86400000))),e=Math.max(s,Math.min(6,Math.round((new Date(j.finish||'2026-11-15')-new Date('2026-11-09'))/86400000)));return `<div class="timeline-row"><span>${jobAction(j)}</span><div class="timeline-track">${j.start&&j.start<='2026-11-15'&&j.finish>='2026-11-09'?`<button class="${['on_deck','complete','not_started'].includes(j.status)?'pattern-label':''}" style="--start:${s};--span:${e-s+1};${styleStatus(j.status)}" data-action="job" data-id="${j.id}">${statuses[j.status][0]}</button>`:''}</div></div>`;}).join('')}</div></div>`;}
function snapshot(){return `<section class="panel"><div class="panel-head"><h2>Monthly Snapshot</h2><span class="muted">November 2026 · synthetic work</span></div><div class="detail-main"><p class="muted">Representative status distribution, not a recreation of every accepted Snapshot calculation.</p><div style="margin-top:20px">${Object.keys(statuses).map(s=>{const n=jobs.filter(j=>j.status===s).length;return `<div class="row" style="margin-bottom:13px"><span style="width:130px">${badge(s)}</span><div style="height:7px;flex:1;background:var(--subtle)"><div style="height:7px;width:${n/jobs.length*100}%;background:${statuses[s][1]}"></div></div><strong style="width:25px;text-align:right">${n}</strong></div>`;}).join('')}</div></div></section>`;}
function pendingBanner(){const n=Object.keys(state.pending).length;return n?`<div class="pending-banner" role="status">${state.direction==='b'?'':icon('calendar')}<div><strong>${n} staged schedule ${n===1?'change':'changes'}</strong><small>Changes not yet saved. Review the proposed dates before saving.</small></div><span class="spacer"></span><button data-action="discard-schedule">Discard</button><button class="primary" data-action="review-schedule">Review changes</button></div>`:'';}
function taskList(){return tasks.filter(t=>state.taskView==='completed'?t.done:!t.done&&(state.taskView==='shared'?t.shared:state.taskView==='mine'?!t.shared:state.taskView==='today'?t.due<='2026-11-17':state.taskView.startsWith('group:')?t.group===state.taskView.slice(6):true)).sort((a,b)=>a.due.localeCompare(b.due));}
function myWork(){const list=taskList();return `<div class="page-heading"><div><div class="eyebrow">Your workspace</div><h1>My Work</h1><p>Your tasks, shared commitments and linked jobs.</p></div><button class="primary" data-action="new-task" ${state.role==='readonly'?'disabled':''}>${icon('plus')} Add task</button></div><div class="task-layout"><aside class="task-sidebar" aria-label="Task views">${[['today','Today'],['all','All Tasks'],['mine','My Tasks'],['shared','Shared Tasks'],['completed','Completed']].map(([v,l])=>`<button data-action="task-view" data-value="${v}" aria-pressed="${state.taskView===v}">${state.direction==='b'?(['today','mine','shared'].includes(v)?icon(({today:'today',mine:'private-task',shared:'shared'})[v]):''):icon(v==='completed'?'check':v==='today'?'sun':'tasks')}${l}</button>`).join('')}<div class="eyebrow">Task groups</div><div class="task-group-nav">${[['Production planning','#537ba3'],['Procurement','#bd8251'],['Coordination','#6c9384']].map(([g,c])=>`<button data-action="task-view" data-value="group:${g}" aria-pressed="${state.taskView==='group:'+g}"><span class="group-dot" style="--group-color:${c}"></span>${g}</button>`).join('')}</div></aside><div><section class="panel"><div class="panel-head"><h2>${({today:'Today',all:'All Tasks',mine:'My Tasks',shared:'Shared Tasks',completed:'Completed'})[state.taskView]||h(state.taskView.slice(6))}</h2><span class="chip">${list.length} tasks</span><span class="spacer"></span><button data-action="task-help">${state.direction==='b'?'':icon('clock')} Workload</button></div><div class="task-summary"><span><strong>${list.filter(t=>t.due<'2026-11-10'&&!t.done).length}</strong> overdue</span><span><strong>${list.reduce((n,t)=>n+t.minutes,0)}</strong> min estimated</span><span>${state.taskView==='today'?'Overdue + next 7 days':'Personal and shared tasks'}</span></div><div class="table-container" tabindex="0" aria-label="Tasks, scroll horizontally"><table class="task-table"><thead><tr><th>Done</th><th>Task / Linked job</th><th>Due date</th><th>Estimated</th><th>Visibility</th><th>Group</th></tr></thead><tbody>${list.map(t=>`<tr><td><button class="task-check ${t.done?'done':''}" data-action="complete-task" data-id="${t.id}" aria-label="${t.done?'Reopen':'Complete'} ${h(t.title)}" ${state.role==='readonly'?'disabled':''}>${t.done?icon('check'):''}</button></td><td style="min-width:240px"><button class="task-title ${t.done?'completed-title':''}" data-action="task" data-id="${t.id}">${h(t.title)}</button><div class="job-meta task-metadata">${sourceIcon('linked-job')}${h(jobs[t.job].number)} · ${h(jobs[t.job].name)} · ${sourceIcon('clip')}${t.files} files</div></td><td class="${t.due<'2026-11-10'&&!t.done?'overdue':''}">${sourceIcon('due')}${date(t.due)}${t.due<'2026-11-10'&&!t.done?' · Overdue':''}${t.due==='2026-11-10'?' · Today':''}</td><td>${sourceIcon('clock')}${t.minutes} min</td><td>${state.direction==='b'?icon(t.shared?'shared':'private-task'):''}${t.shared?'Shared · '+h(t.assignee):'Private'}</td><td><span class="chip">${state.direction==='b'?'<span class="task-group-icon" style="--group-color:'+t.color+'">'+icon('folder')+'</span>':'<span class="group-dot" style="--group-color:'+t.color+'"></span>'}${h(t.group)}</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No tasks match this view.</td></tr>'}</tbody></table></div><div class="table-foot"><span>Personal task colors · separate from Production statuses</span><span>Session only</span></div></section></div></div>`;}
function openJob(id){if(!jobs.find(j=>j.id===id))return;state.selected={type:'job',id};state.tab='Details';state.editing=false;renderInspector();if(!$('#inspector').open)$('#inspector').showModal();}
function renderInspector(){if(!state.selected)return;if(state.selected.type==='task'){renderTaskInspector();return;}const j=jobs.find(j=>j.id===state.selected.id);$('#inspector').innerHTML=`<div class="dialog-header"><div><div class="eyebrow">PRODUCTION INSPECTOR · ${h(j.number)}</div><h2 id="inspector-title">${h(j.name)}</h2><div class="job-meta">${h(j.customer)} · ${h(j.order)}</div></div><span class="spacer"></span><button data-action="share" data-id="${j.id}" aria-label="Share job">${icon('share')}<span class="header-action-label">Share</span></button><button class="ghost close ${state.direction==='b'?'source-close-label':'icon'}" data-action="close-inspector" aria-label="Close Production Inspector">${state.direction==='b'?(state.mobile?'Back':'Close'):icon('close')}</button></div><div class="dialog-tabs" role="tablist" aria-label="Job sections">${['Details','Planning','Job Updates','Files','Recent Changes'].map(t=>`<button role="tab" aria-selected="${state.tab===t}" data-action="inspector-tab" data-tab="${t}">${t}${t==='Files'?` (${j.attachments})`:t==='Job Updates'?` (${fixtureUpdateSummary(j).total})`:''}</button>`).join('')}</div><div class="inspector-content">${jobInspectorBody(j)}</div>`;}
function activity(j){return `<div class="activity-item"><strong>Production details reviewed</strong><small>Planner A · Nov 9, 2026 at 2:15 PM</small></div><div class="activity-item">Material status: Unknown → ${materials[j.material]}<small>Planner B · Nov 6, 2026 at 10:40 AM</small></div><div class="activity-item">Job added to the Production Pipeline<small>Planner A · Nov 2, 2026 at 8:30 AM · Synthetic history</small></div>`;}
function jobInspectorBody(j){if(state.tab==='Files')return `<div class="detail-main"><div class="row between"><h3>Job files (${j.attachments})</h3><button data-action="fixture-file">${sourceIcon('upload','plus')} Add files</button></div><p class="muted">Representative filenames only. No business documents are included.</p>${['Shop drawings · Revision B.pdf','Approved finish sample.pdf','Production work order.pdf'].slice(0,Math.min(3,j.attachments)).map((n,i)=>`<div class="file-item">${icon('file')}<div><p>${n}</p><small>Fixture · ${[248,126,84][i]} KB · Nov ${6+i}, 2026</small></div><span class="spacer"></span><button data-action="fixture-file">Preview</button></div>`).join('')}${!j.attachments?'<div class="empty">No fixture attachments.</div>':''}</div>`;if(state.tab==='Job Updates')return fixtureJobUpdatesPanel(j);if(state.tab==='Recent Changes')return `<div class="detail-main"><h3>${sourceIcon('history')}Recent Changes</h3>${activity(j)}</div>`;if(state.tab==='Planning')return `<div class="detail-main"><h3>Planning workspace</h3><p class="muted">Review planning details for this job.</p><div class="detail-note" style="margin-top:18px"><strong>Planned dates stay separate from ordinary edits.</strong><p>Use Details → Stage dates to prepare schedule changes for review.</p></div><div style="margin-top:17px">${badge(j.status)} <span class="chip">${j.start?'Dates available':'Needs Dates'}</span></div></div>`;return `<div class="detail-grid"><section class="detail-main"><div class="row between" style="margin-bottom:20px"><h3>Job identity & details</h3><button data-action="edit-job" ${state.role==='readonly'?'disabled':''}>${state.editing?'Cancel edit':'Edit details'}</button></div><form id="job-edit-form"><div class="field-grid">${[['Project',j.name,'name'],['Customer',j.customer,'customer'],['Job number',j.number,'number'],['Work order',j.order,'order'],['Requested delivery',j.delivery,'delivery'],['Estimated labor (hours)',j.labor,'labor'],['Estimate',j.estimate,'estimate'],['Operations',j.owner,'owner']].map(([l,v,k])=>`<label class="field"><span>${l}</span>${state.editing?`<input name="${k}" value="${h(v)}" type="${k==='delivery'?'date':k==='labor'?'number':'text'}" ${k==='labor'?'min="0" step="1"':''} required>`:`<b>${k==='delivery'?date(v):h(v)}</b>`}</label>`).join('')}<label class="field wide"><span>Remarks</span>${state.editing?`<textarea name="remarks">${h(j.remarks)}</textarea>`:`<b style="font-weight:400">${h(j.remarks)}</b>`}</label></div>${state.editing?'<div class="row" style="margin-bottom:25px"><button class="primary">Save changes</button><span class="muted">Editing details</span></div>':''}</form><div class="detail-note"><strong>Material readiness</strong><p>${j.material==='ready'?'Material is ready for this synthetic job.':j.material==='ordered'?'Procurement has started. Ordered remains blocked until all required material is ready.':'Review material requirements before releasing this job to Production.'}</p></div><h3 style="margin-top:27px">Recent activity</h3>${activity(j)}</section><aside class="detail-sidebar"><div class="side-block"><h3>Operational status</h3><div class="field"><span>Production status</span>${badge(j.status)}</div><div class="field"><span>Material status</span>${material(j.material)}</div><span class="chip">${j.start?'Dates available':'Needs Dates'}</span><button data-action="status-edit" data-id="${j.id}" style="margin-top:15px" ${state.role==='readonly'?'disabled':''}>Change status</button></div><div class="side-block"><h3>Production schedule</h3><form id="schedule-form" data-id="${j.id}"><label class="field"><span>Planned start</span><input type="date" name="start" value="${state.pending[j.id]?.start||j.start}" required></label><label class="field"><span>Planned finish</span><input type="date" name="finish" value="${state.pending[j.id]?.finish||j.finish}" required></label><button ${state.role==='readonly'?'disabled':''}>${state.direction==='b'?'':icon('calendar')} Stage dates</button></form><p class="muted" style="font-size:10px;margin-top:8px">Staging does not change the saved schedule. Review changes before saving.</p>${state.pending[j.id]?'<button data-action="review-schedule" class="primary" style="margin-top:10px">Review staged change</button>':''}</div><div><h3>Connected work</h3><button data-action="linked-tasks" data-id="${j.id}">${sourceIcon('clipboard','tasks')} View linked tasks</button><button data-action="share" data-id="${j.id}" style="margin-top:8px">${icon('share')} Share this job</button></div></aside></div>`;}
function openTask(id){if(!tasks.find(t=>t.id===id))return;state.selected={type:'task',id};state.editing=false;renderTaskInspector();if(!$('#inspector').open)$('#inspector').showModal();}
function renderTaskInspector(){const t=tasks.find(t=>t.id===state.selected.id),j=jobs[t.job];$('#inspector').innerHTML=`<div class="dialog-header"><div><div class="eyebrow">MY WORK · TASK INSPECTOR · SYNTHETIC</div><h2 id="inspector-title">Task details</h2><div class="job-meta">${t.shared?'Shared with '+h(t.assignee):'Private task'} · Created by Planner A</div></div><button class="icon ghost close" data-action="close-inspector" aria-label="Close Task Inspector">${icon('close')}</button></div><div class="inspector-content" style="height:calc(100% - 145px)"><form id="task-form"><div class="detail-grid"><section class="detail-main"><div class="field-grid"><label class="field wide"><span>Title</span><input name="title" value="${h(t.title)}" required></label><label class="field wide"><span>Notes</span><textarea name="notes" style="height:120px">${h(t.notes)}</textarea></label><label class="field"><span>Due date</span><input type="date" name="due" value="${t.due}" required></label><label class="field"><span>Estimated time (minutes)</span><input type="number" name="minutes" min="0" max="10080" value="${t.minutes}" required></label><label class="field"><span>Share with</span><select name="share"><option value="private" ${!t.shared?'selected':''}>Private · only me</option>${['Planner A','Planner B','Planner C'].map(p=>`<option ${t.shared&&p===t.assignee?'selected':''}>${p}</option>`).join('')}</select></label><label class="field"><span>Task Group</span><select name="group">${['Production planning','Procurement','Coordination'].map(g=>`<option ${t.group===g?'selected':''}>${g}</option>`).join('')}</select></label><label class="field"><span>Task color (personal)</span><select name="color"><option value="#537ba3">Blue</option><option value="#6c9384">Teal</option><option value="#bd8251">Orange</option></select></label><div class="field"><span>Display color</span><b>${sourceIcon('info')}Uses the Task Group color</b></div></div><h3>Attachments (${t.files})</h3><div class="file-item">${state.direction==='b'?(t.files?icon('clip'):''):icon('file')}<div><p>${t.files?'Reference notes.pdf':'No fixture files attached'}</p><small>Local review placeholder</small></div><span class="spacer"></span><button type="button" data-action="fixture-file">${sourceIcon('upload','clip')} Add files</button></div></section><aside class="detail-sidebar"><h3>Linked Production job</h3><p><b>${h(j.name)}</b></p><p class="muted" style="font-size:11px;margin:5px 0 14px">${h(j.number)} · ${h(j.customer)}</p>${badge(j.status)}<button type="button" data-action="task-linked-job" data-id="${j.id}" style="margin-top:15px">${sourceIcon('linked-job','link')} Open linked Job</button><div class="detail-note" style="margin-top:25px"><strong>${t.done?'Completed':'Open task'}</strong><p>Completion is independent of linked Production status.</p></div></aside></div></form></div><div class="dialog-footer"><button data-action="complete-task" data-id="${t.id}" ${state.role==='readonly'?'disabled':''}>${state.direction==='b'?'':icon('check')} ${t.done?'Reopen':'Mark complete'}</button><span class="spacer"></span><button data-action="close-inspector">Cancel</button><button class="primary" type="submit" form="task-form" ${state.role==='readonly'?'disabled':''}>Save changes</button></div>`;$('#task-form [name=color]').value=t.personalColor||t.color;}
function closeInspector(){if(state.editing){utility('Discard changes?','<p>Close the Inspector and discard any changes that have not been saved?</p>','<button data-action="close-utility">Keep editing</button><button data-action="confirm-close">Discard edits</button>');return;}$('#inspector').close();state.selected=null;}
function shareJob(j){const u=new URL(location.origin+'/');u.searchParams.set('open-production-job',j.id);utility('Share job',`<p>Share a link to this job or prepare a Messaging draft.</p><div class="detail-note"><strong>${h(j.name)}</strong><p>${h(j.number)} · ${h(j.customer)}</p></div><label class="field" style="margin-top:18px"><span>Job link</span><input id="share-url" readonly value="${h(u.href)}"></label><p class="muted" style="font-size:10px;margin-top:8px">Sharing this link does not grant access.</p>`,`<button data-action="copy-link">${sourceIcon('copy','link')} Copy link</button><button class="primary" data-action="share-message" data-id="${j.id}" ${(state.direction==='b'?!navProfile().messagingWrite:state.role==='readonly')?'disabled':''}>${icon('mail')} Prepare Messaging draft</button>`);}
function messages(job=null){utility('Messaging',`<p>Global Inbox · simulated conversation. No messages leave this browser.</p><div class="message-thread"><div class="avatar">PB</div><div><strong>Planner B</strong><div class="muted" style="font-size:11px">Production coordination · 3 unread</div></div></div><div id="conversation"><div class="message-bubble"><strong>Planner B</strong><p>Can you confirm the delivery window for the lobby job?</p><small>10:24 AM · synthetic message</small></div><div class="message-bubble mine"><p>I’ll check site access notes and update the job.</p><small>10:27 AM · synthetic message</small></div>${state.messages.map(m=>`<div class="message-bubble mine"><p>${h(m)}</p><small>Just now · local simulation</small></div>`).join('')}</div>${job?`<div class="detail-note"><strong>${h(job.name)}</strong><p>${h(job.number)} · ${h(job.customer)} · Job reference</p></div>`:''}<form id="message-form"><div class="compose"><button type="button" class="icon" data-action="fixture-file" aria-label="Attach a file">${icon('clip')}</button><input name="message" aria-label="Message draft" required placeholder="Write a local message…" value="${job?h('Please review '+location.origin+'/?open-production-job='+job.id):''}"><button class="primary" ${(state.direction==='b'?!navProfile().messagingWrite:state.role==='readonly')?'disabled':''}>${sourceIcon('send')}Send</button></div></form>`);}
function tenbot(){utility('TenBot',`<div class="row"><div class="bot-avatar">${icon('bot')}</div><div><strong>Your operations workspace</strong><p class="muted" style="font-size:11px">Scripted demonstration · no inference</p></div></div><div class="message-bubble"><p>I can help review this synthetic pipeline. Choose a question.</p></div><div class="row wrap"><button data-action="bot-question" data-value="blocked">Which jobs need material attention?</button><button data-action="bot-question" data-value="delivery">What is due this week?</button></div><div id="bot-response"></div><p class="muted" style="font-size:10px;margin-top:20px">Compact review modal approximates the source sidepane. The accepted workspace and action-review permissions remain unchanged.</p>`);}
function guide(){utility('Design review guide',`<p>Three visual systems over one synthetic dataset. Switch without losing your current screen or staged dates.</p><div class="guide-grid"><div class="guide-tile"><h3>A · Refined Enterprise</h3><p>Document-like hierarchy, quiet separators, familiar shell. Lowest transition risk.</p></div><div class="guide-tile"><h3>B · Modern Operations</h3><p>Stronger data scanning and connected surfaces. Selected visual foundation with accepted navigation grouping and interactions.</p></div><div class="guide-tile"><h3>C · Industrial Premium</h3><p>Graphite and warm metal, technical labels and square geometry. Distinct manufacturing identity.</p></div><div class="guide-tile"><h3>Before · reconstruction</h3><p>Source-derived type, borders and colors on fixtures, not an authenticated screenshot.</p></div></div><h3>Try these paths</h3><ol><li>Switch Jobs / My Tasks / Both, density and month. Open a job, task or + overflow.</li><li>Search the Pipeline; the calendar keeps its own filters.</li><li>Open a Job → edit details, stage dates → review → Save all changes.</li><li>Share → copy a preview link or prepare a Messaging draft.</li><li>Open My Work → edit, complete, then reopen a task in Completed.</li><li>Compare Light/Dark and Mobile/Desktop. The phone calendar scrolls horizontally.</li></ol><h3>Boundaries</h3><p>Fixture edits reset on reload. Visual/calendar preferences use a namespaced local key. Planner / Read only demonstrates gating; it is not authentication. Messages and approval are local simulations. Other module entries open source-context summaries.</p><p>B preserves accepted navigation. Dirty-close guard, default table geometry and summary metrics remain proposals requiring review. No accepted source has changed.</p><p><a href="/ASSESSMENT.md" target="_blank" rel="noopener">Source-grounded assessment and roadmap</a> · <a href="/README.md" target="_blank" rel="noopener">Review instructions</a></p>`);}
function menu(title,items){utility(title,`<p>Existing source destinations. The prototype does not enter the authenticated application.</p>${items.map(([l,r,n])=>`<div class="file-item"><div><strong>${l}</strong><div class="mono muted" style="font-size:10px">${r}</div><p class="muted" style="font-size:11px;margin-top:5px">${n}</p></div></div>`).join('')}`);}
const menus={intake:['Intake & Bids',[['Intake','/pre-production','Active profile + viewIntake. Preserve Overview, Updates, Files and guarded conversion. Projected dates remain separate from Production commitments.']]],reporting:['Reporting',[['Manpower','/manpower-reporting','AM/PM entry, groups, complete-group search and selected-period analytics.'],['Material Usage','/material-usage','Separate operational reporting stream.'],['Daily Production','Disabled in source','Preserve disabled state.']]],inventory:['Inventory',[['Current Inventory','/inventory','Reserved/general stock, quantities, locations and transaction history.'],['Pending Receivals','/inventory?section=pending-receivals#pending-receivals','Collapsed with attention count. Preserve partial receiving, actor confirmation, retry and undo.'],['Inventory Activity','/activity','Auditable transaction history.']]],toolbox:['Toolbox',[['Sample Form Generator','/samples','Existing generator.'],['Proposal Generator','/proposals','Existing generator.'],['PO Generator','/purchasing','Preserve draft, issue and document behavior.'],['Letter of Transmittal','/transmittals','Existing form workflow.'],['Contacts','/contacts','Requires readOperationalData.'],['Catalog','/catalog','Sanitized vendor datasets not supplied.']]]};
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.direction){state.direction=b.dataset.direction;render();return;}if(b.id==='theme-toggle'){state.theme=state.theme==='light'?'dark':'light';theme();return;}if(b.id==='viewport-toggle'){state.mobile=!state.mobile;if(state.direction==='b')render();else theme();return;}if(b.id==='review-notes'){guide();return;}const a=b.dataset.action,id=b.dataset.id;if(!a)return;if(state.editing&&['review-schedule','status-edit','share'].includes(a)){notify('Save or cancel ordinary edits before continuing.');return;}if(state.newTaskId&&['task-linked-job','complete-task'].includes(a)){notify('Save the new task before opening linked work or completing it.');return;}
if(a==='production'||a==='tasks'){if($('#utility').open)$('#utility').close();state.page=a==='production'?'production':'tasks';if(state.direction==='b'){navigateSource(a==='production'?'/':'/my-work');return;}render();return;}
if(menus[a]){menu(...menus[a]);return;}if(a==='guide'){guide();return;}if(a==='close-utility'){$('#utility').close();return;}if(a==='close-inspector'){closeInspector();return;}if(a==='confirm-close'){state.editing=false;$('#utility').close();$('#inspector').close();state.selected=null;return;}
if(a==='job-updates'||a==='job-files'){event.stopPropagation();$('#utility').close();openJob(id);if(a==='job-updates'){markFixtureUpdatesSeen(id);state.tab='Job Updates';}else state.tab='Files';render();renderInspector();return;}if(a==='job'||a==='task'){$('#utility').close();if(a==='job')openJob(id);else openTask(id);return;}if(a==='task-linked-job'){if(state.editing){notify('Save or cancel task edits before opening its linked Job.');return;}openJob(id);return;}
if(a==='mode'){state.mode=b.dataset.mode;render();return;}if(a==='collapse'){state.expanded=!state.expanded;render();return;}if(a==='contents'){state.contents=b.dataset.value;render();return;}if(a==='month'){const d=new Date(state.year,state.month+Number(b.dataset.delta),1);state.year=d.getFullYear();state.month=d.getMonth();render();return;}if(a==='table-view'){state.tableView=b.dataset.value;render();return;}if(a==='task-view'){state.taskView=b.dataset.value;render();return;}
if(a==='day'){const items=calendarItems().filter(i=>i.start<=b.dataset.date&&i.finish>=b.dataset.date);utility('Workload · '+date(b.dataset.date),`<p>Complete day list, including items hidden by the density setting.</p>${items.map(i=>`<div class="file-item"><div>${i.type==='job'?badge(i.status):'<span class="chip">'+sourceIcon(i.done?'check':'tasks')+'Task</span>'}<p style="margin-top:6px">${h(i.label)}</p></div><span class="spacer"></span><button data-action="${i.type}" data-id="${i.id}">Inspect</button></div>`).join('')}`);return;}
if(a==='inspector-tab'){if(state.editing){notify('Save or cancel edits before switching sections.');return;}state.tab=b.dataset.tab;if(state.tab==='Job Updates'){markFixtureUpdatesSeen(state.selected.id);render();}renderInspector();return;}if(a==='edit-job'){state.editing=!state.editing;renderInspector();return;}
if(a==='share'){shareJob(jobs.find(j=>j.id===id));return;}if(a==='copy-link'){try{await navigator.clipboard.writeText($('#share-url').value);notify('Job link copied.');}catch{$('#share-url').focus();$('#share-url').select();notify('Copy the selected link with Ctrl+C.');}return;}if(a==='share-message'){messages(jobs.find(j=>j.id===id));return;}if(a==='messages'){messages();return;}if(a==='tenbot'){tenbot();return;}
if(a==='bot-question'){const list=b.dataset.value==='blocked'?jobs.filter(j=>active.includes(j.status)&&j.material!=='ready'):jobs.filter(j=>active.includes(j.status)&&j.delivery>='2026-11-09'&&j.delivery<='2026-11-15');$('#bot-response').innerHTML=`<div class="message-bubble"><strong>Scripted fixture response</strong><p>${list.length} matching jobs.</p>${list.map(j=>`<div class="file-item" style="padding:8px 0">${jobAction(j)}<span class="spacer"></span>${b.dataset.value==='blocked'?material(j.material):date(j.delivery)}</div>`).join('')}<small>No model called.</small></div>`;return;}
if(a==='notifications'){utility('Notifications','<p>Personal synthetic activity. Generic Job Updates are not automatically personal notifications.</p><div class="file-item"><div><strong>Planner B shared a task</strong><p>Coordinate lobby delivery window</p><small>10 minutes ago · synthetic</small></div><button data-action="notification-task">Open</button></div><div class="file-item"><div><strong>New message from Planner B</strong><p>Production coordination</p></div><button data-action="messages">Open</button></div>','<button data-action="mark-read">Mark all read</button>');return;}if(a==='mark-read'){notify('Synthetic notifications marked read.');$('#utility').close();return;}if(a==='notification-task'){$('#utility').close();openTask('task-3');return;}
if(a==='role'){utility('Preview permissions','<p>Visual gating for a synthetic reviewer; not authentication or replacement permission logic.</p>','<button data-action="set-role" data-value="readonly">Read only</button><button class="primary" data-action="set-role" data-value="planner">Planner</button>');return;}if(a==='set-role'){state.role=b.dataset.value;$('#utility').close();render();if($('#inspector').open)renderInspector();notify('Preview role: '+state.role);return;}
if(a==='more'){menu('More destinations',[['Dashboard · Production','/','Jobs remains the mobile primary entry.'],...menus.intake[1],...menus.reporting[1],...menus.inventory[1],...menus.toolbox[1]]);return;}
if(a==='columns'){utility('Table columns','<p>Table demonstrates the administrative field set; Overview prioritizes identity, status, dates and labor. Accepted column visibility, resizing, sticky identity and saved widths must survive modernization. These preference controls are not reimplemented here.</p>','<button data-action="choose-view" data-value="overview">Overview</button><button class="primary" data-action="choose-view" data-value="table">Show full Table</button>');return;}if(a==='choose-view'){state.tableView=b.dataset.value;$('#utility').close();render();return;}
if(a==='fixture-file'){notify('File control demonstration only. No file transfer.');return;}if(a==='linked-tasks'){const index=jobs.findIndex(j=>j.id===id);utility('Linked tasks',tasks.filter(t=>t.job===index).map(t=>`<div class="file-item"><span>${h(t.title)}</span><span class="spacer"></span><button data-action="task" data-id="${t.id}">Inspect</button></div>`).join('')||'<p>No fixture tasks linked.</p>');return;}
if(a==='task-help'){utility('Estimated workload','<p>Today includes overdue tasks and the next seven days. Completion, private/shared visibility, groups and estimated minutes mirror source concepts.</p><p>Source sort/group/delegation controls are not fully reproduced. No invented task priority or workflow status.</p>');return;}
if(a==='complete-task'){if(state.editing){notify('Save or cancel edits before changing completion.');return;}const t=tasks.find(t=>t.id===id);t.done=!t.done;render();if($('#inspector').open&&state.selected?.type==='task')renderTaskInspector();notify(t.done?'Task completed.':'Task reopened.');return;}
if(a==='discard-schedule'){utility('Discard staged dates?','<p>Discard proposed dates? Saved dates will remain unchanged.</p>','<button data-action="close-utility">Keep changes</button><button data-action="confirm-discard-schedule">Discard staged dates</button>');return;}if(a==='confirm-discard-schedule'){state.pending={};$('#utility').close();render();if($('#inspector').open)renderInspector();notify('Schedule changes discarded.');return;}
if(a==='review-schedule'){const entries=Object.entries(state.pending);utility('Review schedule changes',`<p>Review saved and proposed dates before saving all changes.</p>${entries.map(([id,p])=>{const j=jobs.find(j=>j.id===id);return `<div class="file-item"><div><strong>${h(j.name)}</strong><p class="muted">Saved: ${date(j.start)}–${date(j.finish)}</p><p>Proposed: ${date(p.start)}–${date(p.finish)}</p></div></div>`;}).join('')}<form id="approval-form" style="margin-top:18px"><label class="field"><span>Review attribution</span><input name="actor" required value="Synthetic reviewer"></label><p class="muted" style="font-size:10px;margin-top:10px">Saved dates remain unchanged until you save all changes.</p></form>`,`<button data-action="close-utility">Back</button><button class="primary" type="submit" form="approval-form" ${!entries.length||state.role==='readonly'?'disabled':''}>Save all changes</button>`);return;}
if(a==='status-edit'){const j=jobs.find(j=>j.id===id);utility('Change status',`<p>Update the Production and material status for this job.</p><form id="status-form" data-id="${id}"><div class="field-grid"><label class="field"><span>Production status</span><select name="status">${Object.keys(statuses).map(s=>`<option value="${s}" ${s===j.status?'selected':''}>${statuses[s][0]}</option>`).join('')}</select></label><label class="field"><span>Material status</span><select name="material">${Object.keys(materials).map(s=>`<option value="${s}" ${s===j.material?'selected':''}>${materials[s]}</option>`).join('')}</select></label></div></form>`,'<button data-action="close-utility">Cancel</button><button class="primary" form="status-form">Save changes</button>');return;}
if(a==='new-job'){utility('Add synthetic job','<p>Minimal fixture composer for form review. Accepted job creation is not reimplemented.</p><form id="new-job-form"><div class="field-grid"><label class="field wide"><span>Project name</span><input name="name" required placeholder="Synthetic project"></label><label class="field"><span>Customer</span><input name="customer" placeholder="Synthetic customer"></label><label class="field"><span>Requested delivery</span><input name="delivery" type="date" value="2026-12-10" required></label></div></form>','<button data-action="close-utility">Cancel</button><button class="primary" form="new-job-form">'+sourceIcon('plus')+'Create Job</button>');return;}if(a==='new-task'){const t={...tasks[1],id:'task-'+(tasks.length+1),title:'New synthetic task',notes:'',due:'2026-11-10',minutes:15,files:0,done:false};tasks.push(t);state.newTaskId=t.id;openTask(t.id);notify('New local fixture task. Edit and Save.');return;}
});
document.addEventListener('change',event=>{const e=event.target;if(e.id==='density'){state.density=e.value;render();}if(e.id==='workload-view'){state.workloadView=e.value;render();}if(e.id==='status-filter'){state.status=e.value;render();}if(e.id==='sort'){state.sort=e.value;render();}});
document.addEventListener('input',event=>{const e=event.target;if(e.id==='job-search'){state.search=e.value;const list=filteredJobs();$('#job-results').innerHTML=jobResults(list);const summary=$('#pipeline-summary');if(summary)summary.outerHTML=pipelineSummary(list);const p=e.closest('.panel');p.querySelector('.panel-head .chip').textContent=list.length+' jobs';p.querySelector('.table-foot span').textContent=list.length+' displayed · '+jobs.length+' synthetic jobs';}if(e.closest('#task-form'))state.editing=true;});
document.addEventListener('submit',event=>{event.preventDefault();const f=event.target,v=Object.fromEntries(new FormData(f));if(state.role==='readonly'&&!(f.id==='message-form'&&state.direction==='b'&&navProfile().messagingWrite)){notify('Read-only preview. Switch the role fixture to edit business data.');return;}
if(f.id==='schedule-form'){if(state.editing){notify('Save or cancel ordinary edits before staging dates.');return;}if(v.start>v.finish){notify('Planned finish must be on or after planned start.');return;}const j=jobs.find(j=>j.id===f.dataset.id);if(v.start===j.start&&v.finish===j.finish)delete state.pending[j.id];else state.pending[j.id]={start:v.start,finish:v.finish,originalStart:j.start,originalFinish:j.finish};render();renderInspector();notify(state.pending[j.id]?'Schedule changes pending. Review before saving.':'No change; proposal removed.');}
if(f.id==='approval-form'){Object.entries(state.pending).forEach(([id,p])=>{const j=jobs.find(j=>j.id===id);j.start=p.start;j.finish=p.finish;});state.pending={};$('#utility').close();render();if($('#inspector').open)renderInspector();notify('Schedule changes saved.');}
if(f.id==='job-edit-form'){Object.assign(jobs.find(j=>j.id===state.selected.id),v,{labor:Number(v.labor)});state.editing=false;render();renderInspector();notify('Job details saved.');}
if(f.id==='task-form'){Object.assign(tasks.find(t=>t.id===state.selected.id),{title:v.title,notes:v.notes,due:v.due,minutes:Number(v.minutes),shared:v.share!=='private',assignee:v.share==='private'?'You':v.share,group:v.group,personalColor:v.color,color:({'Production planning':'#537ba3',Procurement:'#bd8251',Coordination:'#6c9384'})[v.group]});state.newTaskId=null;state.editing=false;render();renderTaskInspector();notify('Task saved.');}
if(f.id==='message-form'){state.messages.push(v.message);messages();notify('Message added to local simulation.');}
if(f.id==='job-update-form'){const fixture=jobUpdateFixtures.get(state.selected.id)||{status:'ready',hasUnseenActivity:false,updates:[]};fixture.updates.unshift({author:'Review Member',text:v.update,time:'Just now'});jobUpdateFixtures.set(state.selected.id,fixture);render();renderInspector();notify('Update posted.');}
if(f.id==='status-form'){Object.assign(jobs.find(j=>j.id===f.dataset.id),v);$('#utility').close();render();renderInspector();notify('Status updated.');}
if(f.id==='new-job-form'){jobs.push({...jobs[0],id:`00000000-0000-4000-8000-${String(jobs.length+1).padStart(12,'0')}`,name:v.name,customer:v.customer||'Synthetic customer',delivery:v.delivery,number:'Unassigned',order:'Unassigned',start:'',finish:'',status:'not_started',material:'unknown',labor:0,attachments:0,remarks:''});$('#utility').close();render();notify('Synthetic job added without planned dates.');}
});
$('#inspector').addEventListener('cancel',e=>{e.preventDefault();closeInspector();});
$('#inspector').addEventListener('close',()=>{if(!$('#inspector').open){if(state.newTaskId){const i=tasks.findIndex(t=>t.id===state.newTaskId);if(i>=0)tasks.splice(i,1);state.newTaskId=null;render();}state.selected=null;state.editing=false;}});
document.addEventListener('keydown',event=>{const t=event.target;if(!t.matches('[role=tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...t.closest('[role=tablist]').querySelectorAll('[role=tab]')],n=event.key==='Home'?0:event.key==='End'?tabs.length-1:(tabs.indexOf(t)+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length,name=tabs[n].dataset.tab||tabs[n].dataset.mode;tabs[n].click();[...document.querySelectorAll('[role=tab]')].find(t=>(t.dataset.tab||t.dataset.mode)===name)?.focus();});
render();if(query.get('open-production-job'))openJob(query.get('open-production-job'));

const responsiveQuery=matchMedia(NAV_MOBILE_QUERY);responsiveQuery.addEventListener('change',event=>{state.mobile=event.matches;render();});
